"use client";

import { useDroppable } from "@dnd-kit/core";
import { Server } from "lucide-react";

import { Disk, type DiskType } from "@/components/features/storage/disk";
import { cn } from "@/lib/utils";

type ServerBladeProps = {
    id: string;
    name: string;
    disks: DiskType[];
    isMain?: boolean;
};

export function ServerBlade({ id, name, disks, isMain }: ServerBladeProps) {
    const { setNodeRef, isOver } = useDroppable({
        id,
        data: { id, type: "server-blade" },
    });

    return (
        <div
            ref={setNodeRef}
            className={cn(
                "relative flex h-[400px] w-full flex-col gap-4 rounded-xl border-2 border-dashed p-6 transition-all",
                isOver
                    ? "border-primary bg-primary/5 scale-[1.02]"
                    : "border-muted-foreground/20 hover:border-primary/50",
                isMain && "border-solid border-primary/20 bg-muted/50"
            )}
        >
            <div className="flex items-center gap-3">
                <Server className={cn("h-6 w-6", isOver && "text-primary")} />
                <h3 className="font-semibold">{name}</h3>
            </div>

            <div className="flex flex-1 flex-col gap-2 overflow-y-auto rounded-lg bg-background/50 p-2">
                {disks.length === 0 ? (
                    <div className="flex flex-1 items-center justify-center text-sm text-muted-foreground">
                        {isOver ? "Drop to Assign" : "No Disks Assigned"}
                    </div>
                ) : (
                    disks.map((disk) => <Disk key={disk.id} disk={disk} />)
                )}
            </div>

            <div className="flex justify-between text-xs text-muted-foreground">
                <span>Slots: {disks.length}/8</span>
                <span>ZPool: {isMain ? "Creating..." : "Waiting"}</span>
            </div>
        </div>
    );
}
