"use client";

import { useDraggable } from "@dnd-kit/core";
import { HardDrive } from "lucide-react";

import { cn } from "@/lib/utils";

export type DiskType = {
    id: string;
    serial: string;
    size: string;
    status: "available" | "assigned" | "failed";
    slot?: number;
};

export function Disk({ disk }: { disk: DiskType }) {
    const { attributes, listeners, setNodeRef, transform, isDragging } =
        useDraggable({
            id: disk.id,
            data: disk,
            disabled: disk.status !== "available",
        });

    const style = transform
        ? {
            transform: `translate3d(${transform.x}px, ${transform.y}px, 0)`,
        }
        : undefined;

    return (
        <div
            ref={setNodeRef}
            style={style}
            {...listeners}
            {...attributes}
            className={cn(
                "flex cursor-grab items-center gap-3 rounded-lg border bg-card p-3 shadow-sm transition-colors hover:border-primary active:cursor-grabbing",
                disk.status === "assigned" && "cursor-default opacity-50",
                disk.status === "failed" && "border-destructive/50 bg-destructive/10",
                isDragging && "z-50 opacity-50 ring-2 ring-primary ring-offset-2"
            )}
        >
            <div
                className={cn(
                    "flex h-10 w-10 items-center justify-center rounded-full bg-muted",
                    disk.status === "failed" && "bg-destructive/20 text-destructive"
                )}
            >
                <HardDrive className="h-5 w-5" />
            </div>
            <div>
                <p className="text-sm font-medium">{disk.serial}</p>
                <p className="text-xs text-muted-foreground">{disk.size}</p>
            </div>
        </div>
    );
}
