"use client";

import { Disk, type DiskType } from "@/components/features/storage/disk";
import { api } from "@/trpc/react";
import { DndContext, DragEndEvent, DragOverlay, DragStartEvent, PointerSensor, useSensor, useSensors } from "@dnd-kit/core";
import { useEffect, useState } from "react";
import { ServerBlade } from "./server-blade";

export function SetupWizard() {
    // Fetch available disks from tRPC
    const { data: serverDisks, isLoading } = api.disk.list.useQuery();

    const [availableDisks, setAvailableDisks] = useState<DiskType[]>([]);
    const [activeDisk, setActiveDisk] = useState<DiskType | null>(null);
    const [nodeADisks, setNodeADisks] = useState<DiskType[]>([]);
    const [nodeBDisks, setNodeBDisks] = useState<DiskType[]>([]);

    // Sync server state to local state (simplified for MVP)
    useEffect(() => {
        if (serverDisks && availableDisks.length === 0 && nodeADisks.length === 0) {
            // Need to map the readonly array to mutable if needed, or just use as is
            // For this MVP, we just cast or copy
            setAvailableDisks([...serverDisks]);
        }
    }, [serverDisks]);

    const sensors = useSensors(
        useSensor(PointerSensor, {
            activationConstraint: {
                distance: 8,
            },
        })
    );

    function handleDragStart(event: DragStartEvent) {
        const { active } = event;
        const disk = availableDisks.find((d) => d.id === active.id) ||
            nodeADisks.find((d) => d.id === active.id) ||
            nodeBDisks.find((d) => d.id === active.id);

        if (disk) setActiveDisk(disk);
    }

    function handleDragEnd(event: DragEndEvent) {
        const { active, over } = event;
        setActiveDisk(null);

        if (!over) return;

        const diskId = active.id as string;
        const overId = over.id as string;

        // Logic to move disk between available -> nodeA
        // In a real app, this would trigger a tRPC mutation
        if (overId === "node-a") {
            const disk = availableDisks.find(d => d.id === diskId);
            if (disk) {
                setAvailableDisks(prev => prev.filter(d => d.id !== diskId));
                setNodeADisks(prev => [...prev, { ...disk, status: "assigned" }]);
            }
        }
    }

    if (isLoading) return <div>Loading hardware inventory...</div>;

    return (
        <DndContext
            sensors={sensors}
            onDragStart={handleDragStart}
            onDragEnd={handleDragEnd}
        >
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8 p-6">
                {/* Available Disks */}
                <div className="bg-muted/10 rounded-xl p-6 border-2 border-dashed">
                    <h2 className="text-xl font-bold mb-4">Unassigned Disks</h2>
                    <div className="flex flex-col gap-2">
                        {availableDisks.map((disk) => (
                            <Disk key={disk.id} disk={disk} />
                        ))}
                    </div>
                </div>

                {/* Node A (Primary) */}
                <ServerBlade
                    id="node-a"
                    name="Node A (Primary)"
                    disks={nodeADisks}
                    isMain={true}
                />

                {/* Node B (Secondary) */}
                <ServerBlade
                    id="node-b"
                    name="Node B (Secondary)"
                    disks={nodeBDisks}
                />
            </div>

            <DragOverlay>
                {activeDisk ? <Disk disk={activeDisk} /> : null}
            </DragOverlay>
        </DndContext>
    );
}
